-- =============================================================================
-- IMPULSO DIGITAL - ESQUEMA Y DATOS COMPLETOS DE BASE DE DATOS
-- Motor recomendado: PostgreSQL 14+ (compatible con DBeaver, pgAdmin, Supabase, Neon)
-- Incluye: Módulo 1 (CRM & Diagnóstico), Módulo 2 (Portal Cliente SGA),
--          Módulo 3 (QA, SLAs, Freelancers), Papelera de Empresas y Módulo Agro (Guapi Coco).
-- =============================================================================

-- 1. ELIMINACIÓN PREVIA EN CASO DE RE-EJECUCIÓN (CASCADE)
DROP TABLE IF EXISTS guapicoco_harvest_logs CASCADE;
DROP TABLE IF EXISTS guapicoco_palms CASCADE;
DROP TABLE IF EXISTS freelancer_tasks CASCADE;
DROP TABLE IF EXISTS milestones CASCADE;
DROP TABLE IF EXISTS freelancer_profiles CASCADE;
DROP TABLE IF EXISTS training_materials CASCADE;
DROP TABLE IF EXISTS ticket_messages CASCADE;
DROP TABLE IF EXISTS support_tickets CASCADE;
DROP TABLE IF EXISTS deliverables CASCADE;
DROP TABLE IF EXISTS projects CASCADE;
DROP TABLE IF EXISTS interactions CASCADE;
DROP TABLE IF EXISTS diagnostic_answers CASCADE;
DROP TABLE IF EXISTS diagnostics CASCADE;
DROP TABLE IF EXISTS contacts CASCADE;
DROP TABLE IF EXISTS companies CASCADE;
DROP TABLE IF EXISTS audit_logs CASCADE;
DROP TABLE IF EXISTS users CASCADE;

-- =============================================================================
-- 2. DEFINICIÓN DE TABLAS (DDL)
-- =============================================================================

-- Tabla de Usuarios (Autenticación y Roles Multi-tenant)
CREATE TABLE users (
    id SERIAL PRIMARY KEY,
    email VARCHAR(255) UNIQUE NOT NULL,
    full_name VARCHAR(150) NOT NULL,
    hashed_password VARCHAR(255) NOT NULL,
    role VARCHAR(50) NOT NULL DEFAULT 'comercial', -- admin, comercial, cliente, freelancer
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    company_id INTEGER -- Llave foránea diferida a companies(id)
);

-- Tabla de Empresas (Pymes diagnosticadas y gestionadas en CRM)
CREATE TABLE companies (
    id SERIAL PRIMARY KEY,
    name VARCHAR(150) NOT NULL,
    nit VARCHAR(30) UNIQUE,
    sector VARCHAR(50) NOT NULL, -- comercio, servicios, manufactura
    city VARCHAR(100),
    employees INTEGER NOT NULL DEFAULT 1,
    website VARCHAR(255),
    stage VARCHAR(50) NOT NULL DEFAULT 'nuevo', -- nuevo, contactado, propuesta, negociacion, ganado, perdido
    assigned_to_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    is_deleted BOOLEAN NOT NULL DEFAULT FALSE,
    deleted_at TIMESTAMP WITH TIME ZONE,
    deleted_by_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
    delete_reason TEXT
);

-- Vinculación de company_id en users
ALTER TABLE users ADD CONSTRAINT fk_users_company FOREIGN KEY (company_id) REFERENCES companies(id) ON DELETE SET NULL;

-- Tabla de Contactos de Empresas (Habeas Data Ley 1581)
CREATE TABLE contacts (
    id SERIAL PRIMARY KEY,
    company_id INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
    full_name VARCHAR(150) NOT NULL,
    email VARCHAR(255) NOT NULL,
    phone VARCHAR(50),
    position VARCHAR(100),
    data_consent BOOLEAN NOT NULL DEFAULT FALSE,
    consent_at TIMESTAMP WITH TIME ZONE,
    privacy_policy_version VARCHAR(20),
    consent_ip VARCHAR(45),
    marketing_consent BOOLEAN NOT NULL DEFAULT FALSE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

-- Diagnósticos de Madurez Digital
CREATE TABLE diagnostics (
    id SERIAL PRIMARY KEY,
    company_id INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
    contact_id INTEGER NOT NULL REFERENCES contacts(id) ON DELETE CASCADE,
    questionnaire_version VARCHAR(20) NOT NULL DEFAULT '1.0',
    total_score NUMERIC(5, 2) NOT NULL,
    maturity_level VARCHAR(50) NOT NULL, -- inicial, en_desarrollo, intermedio, avanzado
    recommended_package VARCHAR(50) NOT NULL, -- impulso_basico, impulso_integral, impulso_premium
    dimension_scores JSONB NOT NULL,
    priority_actions JSONB NOT NULL,
    converted BOOLEAN NOT NULL DEFAULT FALSE,
    purchased_package VARCHAR(50),
    converted_at TIMESTAMP WITH TIME ZONE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

-- Respuestas individuales a preguntas del diagnóstico
CREATE TABLE diagnostic_answers (
    id SERIAL PRIMARY KEY,
    diagnostic_id INTEGER NOT NULL REFERENCES diagnostics(id) ON DELETE CASCADE,
    question_code VARCHAR(50) NOT NULL,
    dimension VARCHAR(50) NOT NULL,
    option_value VARCHAR(50) NOT NULL,
    points INTEGER NOT NULL
);

-- Historial de Interacciones CRM (Llamadas, WhatsApp, Correos, Notas)
CREATE TABLE interactions (
    id SERIAL PRIMARY KEY,
    company_id INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
    user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
    type VARCHAR(50) NOT NULL, -- llamada, email, reunion, whatsapp, nota, sistema
    summary TEXT NOT NULL,
    occurred_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

-- Proyectos de Transformación Digital (Módulo 2: Portal del Cliente)
CREATE TABLE projects (
    id SERIAL PRIMARY KEY,
    company_id INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
    title VARCHAR(200) NOT NULL,
    package VARCHAR(50) NOT NULL,
    status VARCHAR(50) NOT NULL DEFAULT 'kickoff', -- kickoff, staging, revision, aprobado, finalizado
    progress_percent INTEGER NOT NULL DEFAULT 0,
    staging_url VARCHAR(255),
    production_url VARCHAR(255),
    target_delivery_date TIMESTAMP WITH TIME ZONE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

-- Entregables de Proyecto con Flujo de Aprobación
CREATE TABLE deliverables (
    id SERIAL PRIMARY KEY,
    project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    title VARCHAR(200) NOT NULL,
    description TEXT NOT NULL,
    preview_url VARCHAR(255),
    status VARCHAR(50) NOT NULL DEFAULT 'pendiente', -- pendiente, en_revision, aprobado, ajustes_solicitados
    client_feedback TEXT,
    reviewed_at TIMESTAMP WITH TIME ZONE,
    reviewed_by_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

-- Tickets de Soporte Técnico y Acompañamiento
CREATE TABLE support_tickets (
    id SERIAL PRIMARY KEY,
    company_id INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
    created_by_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    subject VARCHAR(200) NOT NULL,
    description TEXT NOT NULL,
    priority VARCHAR(50) NOT NULL DEFAULT 'media', -- baja, media, alta, urgente
    status VARCHAR(50) NOT NULL DEFAULT 'abierto', -- abierto, en_proceso, resuelto, cerrado
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    resolved_at TIMESTAMP WITH TIME ZONE
);

-- Mensajes de Hilo en Tickets de Soporte
CREATE TABLE ticket_messages (
    id SERIAL PRIMARY KEY,
    ticket_id INTEGER NOT NULL REFERENCES support_tickets(id) ON DELETE CASCADE,
    user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    message TEXT NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

-- Materiales de Capacitación y Transferencia de Conocimiento
CREATE TABLE training_materials (
    id SERIAL PRIMARY KEY,
    title VARCHAR(200) NOT NULL,
    description TEXT NOT NULL,
    category VARCHAR(100) NOT NULL,
    package_required VARCHAR(50),
    video_url VARCHAR(255),
    manual_url VARCHAR(255),
    duration_minutes INTEGER NOT NULL DEFAULT 10,
    order_index INTEGER NOT NULL DEFAULT 0,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

-- Perfiles de Freelancers (Módulo 3: Automatización & QA)
CREATE TABLE freelancer_profiles (
    id SERIAL PRIMARY KEY,
    user_id INTEGER NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE,
    speciality VARCHAR(50) NOT NULL, -- desarrollo_web, diseno_ui_ux, seo_copywriting, crm_automatizacion
    skills JSONB NOT NULL,
    hourly_rate NUMERIC(10, 2) NOT NULL DEFAULT 0.0,
    bank_info VARCHAR(255),
    rating NUMERIC(3, 2) NOT NULL DEFAULT 5.0,
    completed_tasks_count INTEGER NOT NULL DEFAULT 0,
    on_time_delivery_rate NUMERIC(4, 3) NOT NULL DEFAULT 1.0,
    is_available BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

-- Hitos de Pago Condicionados a Aprobación QA / Cliente
CREATE TABLE milestones (
    id SERIAL PRIMARY KEY,
    project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    title VARCHAR(200) NOT NULL,
    stage VARCHAR(50) NOT NULL, -- inicio, aprobacion_diseno, entrega_final
    payout_amount NUMERIC(12, 2) NOT NULL DEFAULT 0.0,
    payment_status VARCHAR(50) NOT NULL DEFAULT 'bloqueado', -- bloqueado, pendiente_aprobacion, liberado, retenido
    requires_client_approval BOOLEAN NOT NULL DEFAULT TRUE,
    client_approved BOOLEAN NOT NULL DEFAULT FALSE,
    qa_approved BOOLEAN NOT NULL DEFAULT FALSE,
    released_at TIMESTAMP WITH TIME ZONE,
    notes TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

-- Tareas Asignadas a Freelancers con Control de SLA y QA
CREATE TABLE freelancer_tasks (
    id SERIAL PRIMARY KEY,
    project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    milestone_id INTEGER REFERENCES milestones(id) ON DELETE SET NULL,
    assigned_freelancer_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
    title VARCHAR(200) NOT NULL,
    description TEXT NOT NULL,
    deliverable_url VARCHAR(255),
    status VARCHAR(50) NOT NULL DEFAULT 'pendiente', -- pendiente, en_proceso, en_qa, completada, rechazada
    priority VARCHAR(50) NOT NULL DEFAULT 'media', -- baja, media, alta, urgente
    sla_hours_allotted INTEGER NOT NULL DEFAULT 48,
    due_date TIMESTAMP WITH TIME ZONE NOT NULL,
    submitted_at TIMESTAMP WITH TIME ZONE,
    completed_at TIMESTAMP WITH TIME ZONE,
    sla_status VARCHAR(50) NOT NULL DEFAULT 'a_tiempo', -- a_tiempo, en_riesgo, vencido
    qa_score INTEGER,
    qa_feedback TEXT,
    qa_checklist JSONB,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

-- Auditoría de Seguridad y Eventos Críticos
CREATE TABLE audit_logs (
    id SERIAL PRIMARY KEY,
    action VARCHAR(100) NOT NULL,
    details TEXT,
    user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
    company_id INTEGER REFERENCES companies(id) ON DELETE SET NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

-- Módulo Fitosanitario Agroindustrial: Palmas de Coco Finca Guapi Coco (4 Ha)
CREATE TABLE guapicoco_palms (
    id SERIAL PRIMARY KEY,
    code VARCHAR(30) UNIQUE NOT NULL,
    lot VARCHAR(50) NOT NULL DEFAULT 'Lote 1 (Norte)',
    latitude NUMERIC(10, 7) NOT NULL,
    longitude NUMERIC(10, 7) NOT NULL,
    variety VARCHAR(50) NOT NULL DEFAULT 'alto_pacifico',
    planted_year INTEGER NOT NULL DEFAULT 2019,
    last_coconuts_count INTEGER NOT NULL DEFAULT 15,
    annual_coconuts_count INTEGER NOT NULL DEFAULT 75,
    active_bunches INTEGER NOT NULL DEFAULT 6,
    health_status VARCHAR(20) NOT NULL DEFAULT 'sana', -- sana, enferma, muriendo
    symptoms TEXT NOT NULL,
    diagnostic_details TEXT NOT NULL,
    treatment_plan TEXT,
    last_inspected_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

-- Registro de Cosechas por Palma
CREATE TABLE guapicoco_harvest_logs (
    id SERIAL PRIMARY KEY,
    palm_id INTEGER NOT NULL REFERENCES guapicoco_palms(id) ON DELETE CASCADE,
    harvest_date TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    coconuts_harvested INTEGER NOT NULL,
    quality_grade VARCHAR(20) NOT NULL DEFAULT 'Primera',
    notes TEXT
);

-- Índices estratégicos para alto rendimiento
CREATE INDEX idx_companies_stage ON companies(stage);
CREATE INDEX idx_companies_is_deleted ON companies(is_deleted);
CREATE INDEX idx_projects_company ON projects(company_id);
CREATE INDEX idx_deliverables_project ON deliverables(project_id);
CREATE INDEX idx_tasks_freelancer ON freelancer_tasks(assigned_freelancer_id);
CREATE INDEX idx_tasks_status ON freelancer_tasks(status);
CREATE INDEX idx_palms_lot ON guapicoco_palms(lot);
CREATE INDEX idx_palms_health ON guapicoco_palms(health_status);

