INSERT INTO projects (id, company_id, title, package, status, progress_percent, staging_url, production_url, target_delivery_date, created_at, updated_at) VALUES (2, 13, 'EL DIALOGO', 'impulso_integral', 'kickoff', 5, '', NULL, NULL, '2026-10-05 19:20:44.035022', '2026-10-05 19:20:44.035022');
INSERT INTO projects (id, company_id, title, package, status, progress_percent, staging_url, production_url, target_delivery_date, created_at, updated_at) VALUES (3, 12, 'Sistema de Georreferenciación, Censo y Fitosanidad de Palma de Coco (Finca 4 Ha)', 'impulso_integral', 'staging', 85, '/guapicoco', '/sitios/guapicoco/index.html', NULL, '2026-10-05 21:14:09.135750', '2026-10-05 21:14:09.135750');
INSERT INTO deliverables (id, project_id, title, description, preview_url, status, client_feedback, reviewed_at, reviewed_by_id, created_at) VALUES (1, 1, '1. Wireframes y Diseño UI (Figma)', 'Diseño visual de las pantallas principales incluyendo catálogo y carrito de compras.', 'https://figma.com/file/demo', 'aprobado', 'Aprobado. Los colores reflejan muy bien la identidad de la panadería.', NULL, NULL, '2026-10-05 21:14:09.139076');
INSERT INTO deliverables (id, project_id, title, description, preview_url, status, client_feedback, reviewed_at, reviewed_by_id, created_at) VALUES (2, 1, '2. Desarrollo Frontend e Integración WhatsApp', 'Maquetación del sitio en React y botón flotante para enviar pedido preformateado a WhatsApp.', 'https://laespiga.staging.impulsodigital.co', 'aprobado', 'El botón de WhatsApp funciona perfecto desde el celular.', NULL, NULL, '2026-10-05 21:14:09.139076');
INSERT INTO deliverables (id, project_id, title, description, preview_url, status, client_feedback, reviewed_at, reviewed_by_id, created_at) VALUES (3, 1, '3. Configuración de Hosting y Dominio', 'Despliegue en servidores, certificado SSL y configuración del dominio laespiga.co.', 'https://laespiga.staging.impulsodigital.co', 'en_revision', 'Aún veo un error de seguridad al entrar desde algunos navegadores. Por favor revisar el SSL.', NULL, NULL, '2026-10-05 21:14:09.139076');
INSERT INTO deliverables (id, project_id, title, description, preview_url, status, client_feedback, reviewed_at, reviewed_by_id, created_at) VALUES (4, 3, '1. Mapeo Satelital y Polígono de 4 Hectáreas (Lotes 1 a 4)', 'Georreferenciación perimetral de las 4 hectáreas con división en 4 lotes de 1 Ha.', '/guapicoco', 'aprobado', 'Aprobado. El mapa interactivo satelital cubre con exactitud los 4 lotes.', NULL, NULL, '2026-10-05 21:14:09.142109');
INSERT INTO deliverables (id, project_id, title, description, preview_url, status, client_feedback, reviewed_at, reviewed_by_id, created_at) VALUES (5, 3, '2. Módulo de Georreferenciación GPS y Registro en Vivo de Palmas', 'Captura de coordenadas GPS en tiempo real para cada palma de coco y trazado en mapa.', '/guapicoco', 'aprobado', 'Excelente precisión para georreferenciar las palmas directamente en el terreno.', NULL, NULL, '2026-10-05 21:14:09.142109');
INSERT INTO deliverables (id, project_id, title, description, preview_url, status, client_feedback, reviewed_at, reviewed_by_id, created_at) VALUES (6, 3, '3. Conteo de Producción y Algoritmo de Diagnóstico de Salud Fitosanitaria', 'Registro de cosecha por palma, umbrales productivos y detección de palmas sanas, enfermas o muriendo.', '/guapicoco', 'aprobado', 'Muy útil la alerta temprana de picudo negro y las recomendaciones agronómicas.', NULL, NULL, '2026-10-05 21:14:09.142109');
