INSERT INTO guapicoco_palms (id, code, lot, latitude, longitude, variety, planted_year, last_coconuts_count, annual_coconuts_count, active_bunches, health_status, symptoms, diagnostic_details, treatment_plan, last_inspected_at, created_at) VALUES (5, 'GC-LO22-005', 'Lote 1 (Norte)', 5.9754, -74.5854, 'hibrido_pb121', 2019, 6, 35, 3, 'ENFERMA', 'Clorosis foliar moderada en hojas bajeras y presencia de perforación de picudo negro', 'ESTADO DE ALERTA: Rendimiento inferior al potencial agronómico con signos de estrés fitosanitario o nutricional.', '1. Monitoreo intensivo de estípite buscando orificios de entrada de Rhynchophorus palmarum. 2. Plan de fertilización foliar y edáfica: aplicar Cloruro de Potasio (KCl) 2 kg/palma y Sal Común (NaCl) 1.5 kg/palma (esencial para palmas de coco). 3. Poda sanitaria de hojas bajeras cloróticas.', '2026-10-05 20:18:39.165526', '2026-10-05 20:18:39.195183');
INSERT INTO guapicoco_palms (id, code, lot, latitude, longitude, variety, planted_year, last_coconuts_count, annual_coconuts_count, active_bunches, health_status, symptoms, diagnostic_details, treatment_plan, last_inspected_at, created_at) VALUES (6, 'GC-LO23-006', 'Lote 1 (Norte)', 5.9754, -74.58515, 'alto_pacifico', 2020, 20, 76, 10, 'SANA', 'Follaje verde vigoroso, racimos cargados y excelente desarrollo foliar', 'ESTADO ÓPTIMO: Excelente nivel de floración, carga productiva y vigor foliar.', 'Mantener plan de nutrición semestral y desmalezado circular (plateo) en radio de 1.5 metros.', '2026-10-05 20:18:39.165526', '2026-10-05 20:18:39.195183');
