INSERT INTO guapicoco_palms (id, code, lot, latitude, longitude, variety, planted_year, last_coconuts_count, annual_coconuts_count, active_bunches, health_status, symptoms, diagnostic_details, treatment_plan, last_inspected_at, created_at) VALUES (8, 'GC-LO32-008', 'Lote 1 (Norte)', 5.97565, -74.5854, 'alto_pacifico', 2018, 1, 8, 2, 'MURIENDO', 'Necrosis apical severa, flecha colapsada y pudrición de cogollo evidente', 'ESTADO CRÍTICO: Colapso productivo severo o sintomatología letal (posible Pudrición de Cogollo o Marchitez por Anillo Rojo transmitido por picudo negro).', '1. Aislar inmediatamente la palma del resto del lote. 2. Tomar muestra fitopatológica. 3. En caso de Anillo Rojo confirmado, erradicación sanitaria y quema/entierro con cal para evitar contagio a palmas colindantes en un radio de 50 metros. 4. Colocar trampas con feromonas Rhyncolur en el perímetro.', '2026-10-05 20:18:39.165526', '2026-10-05 20:18:39.195183');
